# Test: For each output row i, stack ALL 4 sections at LOCAL ROW i
# Then apply color-priority: non-8 > 8, and within non-8: higher number wins

def solve_stacked_4_sections(in_grid):
    result = [[0]*6 for _ in range(3)]

    for o_r in range(3):
        for c in range(6):
            # Get all 4 sections at local row o_r
            vals = [in_grid[s * 3 + o_r][c] for s in range(4)]

            # Filter to non-zero
            nz_vals = [v for v in vals if v != 0]

            if not nz_vals:
                result[o_r][c] = 0
            else:
                # Priority: prefer non-8, then pick highest
                non_8 = [v for v in nz_vals if v != 8]
                if non_8:
                    result[o_r][c] = max(non_8)
                else:
                    result[o_r][c] = max(nz_vals)

    return result

